const localeIndex = (locale: string) => { const index = PUBLIC_CARD_LOCALES.indexOf(locale as typeof PUBLIC_CARD_LOCALES[number]); return index >= 0 ? index : PUBLIC_CARD_LOCALES.indexOf("en"); };

export function getPublicCardMessages(locale: string): PublicCardMessages {
  const index = localeIndex(locale);
  return Object.fromEntries(PUBLIC_CARD_MESSAGE_KEYS.map((key) => [key, PUBLIC_CARD_ROWS[key][index]])) as PublicCardMessages;
}

export function translatePublicCardBackendValue(field: PublicCardBackendField, input: unknown, locale: string): string {
  const raw = String(input ?? "").trim();
  if (!raw) return "";
  const normalized = raw.toLocaleLowerCase("und");
  const item = PUBLIC_CARD_BACKEND_ROWS[field].find((candidate) => candidate.aliases.includes(normalized));
  return item?.values[localeIndex(locale)] || item?.code || raw;
}
